// @ts-check

import mdx from '@astrojs/mdx';
import sitemap from '@astrojs/sitemap';
import { defineConfig, fontProviders } from 'astro/config';
import { watchMemes } from './src/lib/watch-memes.js';
import { readFileSync } from 'node:fs';

// Opt-in local TLS; certificates are generated by `npm run dev:https`.
const localHttps = process.env.COOKIEBEAR_LOCAL_HTTPS === '1';

// https://astro.build/config
export default defineConfig({
	site: 'https://example.com',
	...(localHttps && { devToolbar: { enabled: false } }),
	integrations: [mdx(), sitemap()],
	vite: {
		plugins: [watchMemes()],
		...(localHttps && {
			server: {
				strictPort: true,
				https: {
					key: readFileSync(new URL('./.local/https/localhost-key.pem', import.meta.url)),
					cert: readFileSync(new URL('./.local/https/localhost.pem', import.meta.url)),
				},
			},
		}),
	},
	fonts: [
		{
			provider: fontProviders.local(),
			name: 'Lora',
			cssVariable: '--font-lora',
			fallbacks: ['serif'],
			options: {
				variants: [
					{
						src: ['./src/assets/fonts/lora-regular.ttf'],
						weight: '400 700',
						style: 'normal',
						display: 'swap',
					},
					{
						src: ['./src/assets/fonts/lora-italic.ttf'],
						weight: '400 700',
						style: 'italic',
						display: 'swap',
					},
				],
			},
		},
	],
});
